        dy = 1
    elif ty < sy:
        dy = -1

    moves = [(dx, 0), (0, dy), (dx, dy), (0, 0)]
    for cx, cy in moves:
        nx, ny = sx + cx, sy + cy
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
